function conspectLink(topic, code) {
  const c = topic && CONSPECTS[topic];
  if (!c) {
    // Нет в старом PDF-конспекте — ищем тему в библиотеке конспектов направления.
    const href = code && typeof progressConspectHref === 'function' ? progressConspectHref(code, topic) : '';
    return href ? `<a class="rev-konspekt-btn" href="${href}" target="_blank" rel="noopener">Открыть конспект: ${esc(String(topic).replace(/^(Тема\s+)?\d+\.\s*/i, ''))}</a>` : '';
  }
  // Конспект открывается через свою страницу-просмотрщик (картинки, без текстового слоя PDF),
  // а не прямой ссылкой на файл — чтобы текст нельзя было выделить и скопировать.
  const doc = c.file.split('/').pop().replace('.pdf', '');
  return `<a class="rev-konspekt-btn" href="konspekt.html?file=${doc}&page=${c.page}" target="_blank" rel="noopener">Открыть конспект: ${esc(c.title)}</a>`;
}

// Ссылка из разбора теста на конспект темы вопроса в библиотеке (там же, откуда идёт «Прогресс
// подготовки»). Пока включена для направлений из REVIEW_TOPIC_LINK_CODES (M078); ссылки нет,
// если темы в библиотеке конспектов нет.
const REVIEW_TOPIC_LINK_CODES = new Set(['M078', 'M019', 'M019E']);
function reviewTopicLink(code, topic) {
  if (!code || !topic || !REVIEW_TOPIC_LINK_CODES.has(code) || typeof progressConspectHref !== 'function') return '';
  const href = progressConspectHref(code, topic);
  return href ? `<a class="rev-konspekt-btn" href="${href}" target="_blank" rel="noopener">Конспект по теме: ${esc(String(topic))}</a>` : '';
}

