/* ---------------------------------------------------------
   MOBILE NAV (burger)
   --------------------------------------------------------- */
function wireMobileNav() {
  const toggle = document.getElementById('navToggle');
  const nav = document.getElementById('mainNav');
  if (!toggle || !nav) return; // страницы без главной навигации (конспекты и т.п.)
  const setOpen = (open) => {
    nav.classList.toggle('is-open', open);
    toggle.classList.toggle('is-open', open);
    toggle.setAttribute('aria-expanded', String(open));
    toggle.setAttribute('aria-label', open ? 'Закрыть меню' : 'Открыть меню');
  };
  toggle.addEventListener('click', () => setOpen(!nav.classList.contains('is-open')));
  nav.querySelectorAll('a').forEach(a => a.addEventListener('click', () => setOpen(false)));
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') setOpen(false); });
  document.addEventListener('click', (e) => {
    if (!nav.classList.contains('is-open')) return;
    if (!e.target.closest('#mainNav') && !e.target.closest('#navToggle')) setOpen(false);
  });
}

// Плавное появление статичных блоков при скролле (feature-карточки, шаги «Как поступить»,
// стат «О нас») — 147 карточек каталога сюда намеренно не включены: список часто
// перерисовывается при поиске/фильтрах, и переанимация на каждый ререндер только мешала бы.
function initScrollReveal() {
  // .card/.kcat-list элементы намеренно исключены — список из 147 групп
  // перерисовывается при поиске/фильтрации, повторный reveal на каждый ре-рендер даст дёрганье.
  const els = document.querySelectorAll(
    '.feat-card, .path-step, .about-us-text, .section-head, .contact-inner, .dir-card'
  );
  if (!els.length) return;
  els.forEach(el => el.classList.add('reveal'));
  if (!('IntersectionObserver' in window)) { els.forEach(el => el.classList.add('on')); return; }
  const io = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) { entry.target.classList.add('on'); io.unobserve(entry.target); }
    });
  }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
  els.forEach(el => io.observe(el));
}

// Анимация «тропы абитуриента»: линия «дорисовывается» и узлы проявляются
// по очереди при попадании секции в область видимости (однократно).
function initPathTimeline() {
  const timeline = document.getElementById('pathTimeline');
  if (!timeline) return;
  const nodes = timeline.querySelectorAll('.path-node');
  if (!('IntersectionObserver' in window)) {
    timeline.classList.add('is-drawn');
    nodes.forEach(n => n.classList.add('on'));
    return;
  }
  const lineIO = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) { timeline.classList.add('is-drawn'); lineIO.unobserve(timeline); }
    });
  }, { threshold: 0.15 });
  lineIO.observe(timeline);

  const nodeIO = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) { e.target.classList.add('on'); nodeIO.unobserve(e.target); }
    });
  }, { threshold: 0.3, rootMargin: '0px 0px -60px 0px' });
  nodes.forEach((n, i) => {
    n.style.transitionDelay = (i * 0.12) + 's';
    nodeIO.observe(n);
  });
}

function initHeaderContrast() {
  const header = document.getElementById('siteHeader');
  const darkSections = document.querySelectorAll('.section-dark, .contact-band');
  if (!header || !darkSections.length) return;
  let ticking = false;
  function check() {
    ticking = false;
    const probeY = header.offsetHeight / 2;
    const onDark = Array.from(darkSections).some(s => {
      const r = s.getBoundingClientRect();
      return r.top <= probeY && r.bottom >= probeY;
    });
    header.classList.toggle('is-on-dark', onDark);
  }
  window.addEventListener('scroll', () => {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(check);
  }, { passive: true });
  check();
}

